/**
 * Inlay hints for workflow YAML editor
 *
 * Displays inline hints for cron expressions showing human-readable schedule descriptions.
 * Uses @actions/languageservice getInlayHints to get the hint text.
 */

import {EditorView, Decoration, WidgetType} from '@codemirror/view'
import type {DecorationSet} from '@codemirror/view'
import {StateField, StateEffect} from '@codemirror/state'
import {getInlayHints} from '@actions/languageservice'
import {clearCacheEntry} from '@actions/languageservice/utils/workflow-cache'
import {TextDocument} from 'vscode-languageserver-textdocument'
import type {InlayHint} from 'vscode-languageserver-types'
import {getDocumentUri} from './document-uri'

/** Delay before updating hints after typing stops, to avoid excessive re-computation */
const DEBOUNCE_MS = 300

/**
 * Create a text document for the language service, clearing any cached parse results first.
 */
function createTextDocument(content: string): ReturnType<typeof TextDocument.create> {
  const documentUri = getDocumentUri()
  clearCacheEntry(documentUri)
  return TextDocument.create(documentUri, 'yaml', 1, content)
}

/**
 * Widget that renders an inlay hint as an inline element
 */
class InlayHintWidget extends WidgetType {
  label: string
  paddingLeft: boolean
  paddingRight: boolean

  constructor(label: string, paddingLeft: boolean, paddingRight: boolean) {
    super()
    this.label = label
    this.paddingLeft = paddingLeft
    this.paddingRight = paddingRight
  }

  override eq(other: InlayHintWidget): boolean {
    return (
      this.label === other.label && this.paddingLeft === other.paddingLeft && this.paddingRight === other.paddingRight
    )
  }

  override toDOM(): HTMLElement {
    const span = document.createElement('span')
    span.className = 'cm-inlay-hint'
    span.setAttribute('aria-hidden', 'true')
    span.textContent = this.label

    if (this.paddingLeft) {
      span.style.paddingLeft = '1ch'
    }
    if (this.paddingRight) {
      span.style.paddingRight = '1ch'
    }

    return span
  }

  override ignoreEvent(): boolean {
    return true
  }
}

/**
 * Convert LSP InlayHint to CodeMirror position
 */
function getLabelText(hint: InlayHint): string {
  if (typeof hint.label === 'string') {
    return hint.label
  }
  // InlayHintLabelPart[]
  return hint.label.map(part => part.value).join('')
}

/**
 * Effect to update inlay hint decorations
 */
const setInlayHints = StateEffect.define<DecorationSet>()

/**
 * Build decorations from inlay hints
 */
function buildInlayHintDecorations(view: EditorView): DecorationSet {
  try {
    const doc = view.state.doc
    const textDocument = createTextDocument(doc.toString())

    const hints = getInlayHints(textDocument)
    if (hints.length === 0) {
      return Decoration.none
    }

    const decorations: Array<{from: number; to: number; decoration: Decoration}> = []

    for (const hint of hints) {
      // Convert LSP position to CodeMirror position
      const line = doc.line(hint.position.line + 1) // LSP is 0-indexed, CodeMirror is 1-indexed
      const pos = line.from + hint.position.character

      const label = getLabelText(hint)
      const widget = new InlayHintWidget(label, hint.paddingLeft ?? false, hint.paddingRight ?? false)

      decorations.push({
        from: pos,
        to: pos,
        decoration: Decoration.widget({widget, side: 1}),
      })
    }

    // Sort by position and create decoration set
    decorations.sort((a, b) => a.from - b.from)
    return Decoration.set(decorations.map(d => d.decoration.range(d.from, d.to)))
  } catch (error) {
    // eslint-disable-next-line no-console
    console.error('[Language Service] Inlay hints error:', error)
    return Decoration.none
  }
}

/**
 * StateField that manages inlay hint decorations
 */
const inlayHintsField = StateField.define<DecorationSet>({
  create(_state) {
    return Decoration.none
  },
  update(decorations, tr) {
    // Check if there's an explicit update via effect
    for (const effect of tr.effects) {
      if (effect.is(setInlayHints)) {
        return effect.value
      }
    }
    // If document changed, map decorations (they'll be rebuilt by the update plugin)
    if (tr.docChanged) {
      return decorations.map(tr.changes)
    }
    return decorations
  },
  provide(field) {
    return EditorView.decorations.from(field)
  },
})

/**
 * Per-editor debounce timers to avoid race conditions when multiple editors are open
 */
const debounceTimers = new WeakMap<EditorView, ReturnType<typeof setTimeout>>()

/**
 * Track whether initial update has been scheduled
 */
const initialUpdateScheduled = new WeakSet<EditorView>()

/**
 * Schedule an update of inlay hints for a specific editor
 */
function scheduleUpdate(view: EditorView): void {
  const existingTimer = debounceTimers.get(view)
  if (existingTimer) {
    clearTimeout(existingTimer)
  }
  const timer = setTimeout(() => {
    debounceTimers.delete(view)
    const decorations = buildInlayHintDecorations(view)
    view.dispatch({effects: setInlayHints.of(decorations)})
  }, DEBOUNCE_MS)
  debounceTimers.set(view, timer)
}

/**
 * Update listener that triggers inlay hint updates on document changes
 */
const inlayHintsUpdateListener = EditorView.updateListener.of(update => {
  if (update.docChanged || update.viewportChanged) {
    scheduleUpdate(update.view)
  }
})

/**
 * Theme for inlay hints
 */
export const inlayHintsTheme = EditorView.baseTheme({
  '.cm-inlay-hint': {
    color: 'var(--fgColor-muted, var(--color-fg-muted))',
    fontStyle: 'italic',
    fontSize: '0.9em',
  },
  // High contrast mode support
  '@media (forced-colors: active)': {
    '.cm-inlay-hint': {
      color: 'GrayText',
      fontStyle: 'italic',
    },
  },
})

/**
 * Extension that provides inlay hints for workflow YAML files
 *
 * This shows human-readable descriptions inline after cron expressions.
 */
export function workflowInlayHints(): Array<ReturnType<typeof inlayHintsField.init>> {
  return [
    inlayHintsField,
    inlayHintsUpdateListener,
    inlayHintsTheme,
    // Trigger initial update after view is created
    EditorView.updateListener.of(update => {
      // Skip if field not available
      if (!update.view.state.field(inlayHintsField, false)) {
        return
      }
      // Schedule initial update only once per view
      if (!initialUpdateScheduled.has(update.view)) {
        initialUpdateScheduled.add(update.view)
        scheduleUpdate(update.view)
      }
    }),
  ]
}
